INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('29d3a07a-6e40-5747-acd1-104cc0c36854', 'Denmark Act', 'Act No. 1636', 'Act No. 1636 amends existing laws related to annual financial reporting and sustainability reporting in Denmark. It postpones the obligation for companies to report on sustainability for financial years starting between January 1, 2025, and December 31, 2026. The law applies to large companies and small to medium-sized enterprises, with specific provisions for those that have previously engaged auditors for sustainability reporting. The purpose is to align with EU directives and provide flexibility during the transition to new reporting standards. The requirements are mandatory for applicable companies starting from 2027.', 'Act No. 1636 amends existing laws related to annual financial reporting and sustainability reporting in Denmark. It postpones the obligation for companies to report on sustainability for financial years starting between January 1, 2025, and December 31, 2026. The law applies to large companies and small to medium-sized enterprises, with specific provisions for those that have previously engaged auditors for sustainability reporting. The purpose is to align with EU directives and provide flexibility during the transition to new reporting standards. The requirements are mandatory for applicable companies starting from 2027.', 'Act No. 1636 amends existing laws related to annual financial reporting and sustainability reporting in Denmark. It postpones the obligation for companies to report on sustainability for financial years starting between January 1, 2025, and December 31, 2026. The law applies to large companies and small to medium-sized enterprises, with specific provisions for those that have previously engaged auditors for sustainability reporting. The purpose is to align with EU directives and provide flexibility during the transition to new reporting standards. The requirements are mandatory for applicable companies starting from 2027.', 'Denmark', 'climate', 'in_force', '2025-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_38', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'denmark', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('580a5109-3627-51f8-a286-5ebd231a640a', 'Act of 2 May 2024 Denmark', 'Act No. 480 of 2 May 2024 Denmark', 'The Act No. 480 of 2 May 2024 in Denmark amends accounting laws to implement EU directives on sustainable reporting and increased size limits. It impacts businesses, requiring them to disclose sustainability information in their annual reports to align with EU standards.', 'The Act No. 480 of 2 May 2024 in Denmark amends accounting laws to implement EU directives on sustainable reporting and increased size limits. It impacts businesses, requiring them to disclose sustainability information in their annual reports to align with EU standards.', 'The Act No. 480 of 2 May 2024 in Denmark amends accounting laws to implement EU directives on sustainable reporting and increased size limits. It impacts businesses, requiring them to disclose sustainability information in their annual reports to align with EU standards.', 'Denmark', 'climate', 'in_force', '2024-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_37', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'denmark', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca882a72-29e3-59bb-86a3-6b0995de8197', 'Denmark Human Rights Due Diligence Guide for the Danish', 'A Human Rights Due Diligence Guide for the Danish Construction Sector', 'This guide is based on the internationally recognized standards concerning the corporate responsibility to respect human rights. It provides inspiration to actors within the construction sector on due diligence, as well an overview of potential human rights challenges and mitigation measures to consider across the construction value chain.', 'This guide is based on the internationally recognized standards concerning the corporate responsibility to respect human rights. It provides inspiration to actors within the construction sector on due diligence, as well an overview of potential human rights challenges and mitigation measures to consider across the construction value chain.', 'This guide is based on the internationally recognized standards concerning the corporate responsibility to respect human rights. It provides inspiration to actors within the construction sector on due diligence, as well an overview of potential human rights challenges and mitigation measures to consider across the construction value chain.', 'Denmark', 'governance', 'in_force', '2023-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_36', ARRAY['regulations', 'mandatory', 'sdg16', 'denmark', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('65a9c5e9-bf24-5d44-8863-064080e70121', 'Denmark Recommendations for good Corporate Governance', 'Recommendations for good Corporate Governance', 'The main purpose of the Committee''s Recommendations for Good Corporate Governance is to ensure trust in the companies from relevant stakeholders, including shareholders, investors and the surrounding community, through transparent management processes and a high level of information, thereby ensuring long-term value creation and return for shareholders.', 'The main purpose of the Committee''s Recommendations for Good Corporate Governance is to ensure trust in the companies from relevant stakeholders, including shareholders, investors and the surrounding community, through transparent management processes and a high level of information, thereby ensuring long-term value creation and return for shareholders.', 'The main purpose of the Committee''s Recommendations for Good Corporate Governance is to ensure trust in the companies from relevant stakeholders, including shareholders, investors and the surrounding community, through transparent management processes and a high level of information, thereby ensuring long-term value creation and return for shareholders.', 'Denmark', 'governance', 'in_force', '2019-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_18', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg11', 'sdg16', 'denmark', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ab98351b-7bd3-5fce-9023-79cdacc61b35', 'Denmark Recommendations on Corporate Governance, 2017 Version 4 updated', 'Recommendations on Corporate Governance, 2017 Version 4 updated August 2019', 'These are best practice guidelines for the management of companies with shares admitted to trading on a regulated market in Denmark, including Nasdaq Copenhagen A/S. The recommendations should be viewed together with the statutory requirements, including in particular, the Danish Companies Act and the Danish Financial Statements Act, European Union company law, the OECD Principles of Corporate Governance, etc.', 'These are best practice guidelines for the management of companies with shares admitted to trading on a regulated market in Denmark, including Nasdaq Copenhagen A/S. The recommendations should be viewed together with the statutory requirements, including in particular, the Danish Companies Act and the Danish Financial Statements Act, European Union company law, the OECD Principles of Corporate Governance, etc.', 'These are best practice guidelines for the management of companies with shares admitted to trading on a regulated market in Denmark, including Nasdaq Copenhagen A/S. The recommendations should be viewed together with the statutory requirements, including in particular, the Danish Companies Act and the Danish Financial Statements Act, European Union company law, the OECD Principles of Corporate Governance, etc.', 'Denmark', 'climate', 'in_force', '2017-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_34', ARRAY['guidance_frameworks', 'sdg7', 'sdg16', 'denmark', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e0800e69-640d-51fe-82aa-ddf6c07f476c', 'Denmark Proposal for a resolution no. B 82 Proposal', 'Proposal for a resolution no. B 82 Proposal for a parliamentary resolution to make it mandatory for companies to exercise due diligence in the field of human rights and to introduce effective legal remedies', 'Beslutningsforslag nr. B 82 is a proposal for a parliamentary decision in Denmark aimed at making it mandatory for companies to exercise due diligence in the area of ​​human rights. The proposal also calls for the introduction of effective remedies to ensure compliance with this legal obligation. In other words, the proposal seeks to regulate the responsibility of companies in relation to human rights and to ensure that they take necessary measures to protect these rights. It is also important to note that the proposal seeks to establish effective remedies so that companies can be held accountable if they do not comply with these legal requirements.', 'Beslutningsforslag nr. B 82 is a proposal for a parliamentary decision in Denmark aimed at making it mandatory for companies to exercise due diligence in the area of ​​human rights. The proposal also calls for the introduction of effective remedies to ensure compliance with this legal obligation. In other words, the proposal seeks to regulate the responsibility of companies in relation to human rights and to ensure that they take necessary measures to protect these rights. It is also important to note that the proposal seeks to establish effective remedies so that companies can be held accountable if they do not comply with these legal requirements.', 'Beslutningsforslag nr. B 82 is a proposal for a parliamentary decision in Denmark aimed at making it mandatory for companies to exercise due diligence in the area of ​​human rights. The proposal also calls for the introduction of effective remedies to ensure compliance with this legal obligation. In other words, the proposal seeks to regulate the responsibility of companies in relation to human rights and to ensure that they take necessary measures to protect these rights. It is also important to note that the proposal seeks to establish effective remedies so that companies can be held accountable if they do not comply with these legal requirements.', 'Denmark', 'climate', 'in_force', '2017-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_35', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'denmark', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('09f39339-27de-5e17-81ae-545425f54eb4', 'Denmark Recommendations on Corporate Governance', 'Recommendations on Corporate Governance, 2017', 'The purpose of corporate governance is to support value creation and accountable management. The most important aspect of the recommendations is to ensure that investors have an insight into the companies. The Committee assumes that companies comply with statutory requirements in companies accounting, auditing and stock exchange legislation without repeating these requirements in these recommendations.', 'The purpose of corporate governance is to support value creation and accountable management. The most important aspect of the recommendations is to ensure that investors have an insight into the companies. The Committee assumes that companies comply with statutory requirements in companies accounting, auditing and stock exchange legislation without repeating these requirements in these recommendations.', 'The purpose of corporate governance is to support value creation and accountable management. The most important aspect of the recommendations is to ensure that investors have an insight into the companies. The Committee assumes that companies comply with statutory requirements in companies accounting, auditing and stock exchange legislation without repeating these requirements in these recommendations.', 'Denmark', 'climate', 'in_force', '2017-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_8', ARRAY['guidance_frameworks', 'sdg16', 'denmark', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d3990497-f373-59cf-8f0c-af2788e42ed0', 'Denmark environmental assessment of plans and programs and', 'Act on environmental assessment of plans and programs and of specific projects (EIA)', 'The purpose of the Act is to ensure a high level of environmental protection and to contribute to the integration of environmental considerations during the preparation and adoption of plans and programs and by permitting projects with a view to promoting sustainable development, by conducting an environmental assessment of plans, programs and projects that can have a significant impact on the environment.', 'The purpose of the Act is to ensure a high level of environmental protection and to contribute to the integration of environmental considerations during the preparation and adoption of plans and programs and by permitting projects with a view to promoting sustainable development, by conducting an environmental assessment of plans, programs and projects that can have a significant impact on the environment.', 'The purpose of the Act is to ensure a high level of environmental protection and to contribute to the integration of environmental considerations during the preparation and adoption of plans and programs and by permitting projects with a view to promoting sustainable development, by conducting an environmental assessment of plans, programs and projects that can have a significant impact on the environment.', 'Denmark', 'governance', 'in_force', '2016-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_19', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'denmark', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('608e7e0c-faf1-5cdd-93f6-cca22c014e9c', 'Denmark Executive Order on assessment of the impact', 'Executive Order on assessment of the impact of certain public and private facilities on the environment (EIA) pursuant to the Planning Act', 'The "Bekendtgørelse om vurdering af visse offentlige og private anlægs virkning på miljøet (VVM) i medfør af lov om planlægning" is a regulation in Denmark related to assessing the environmental impact of certain public and private projects. Businesses are required to prepare and submit a VVM report if their project meets certain criteria and has the potential to significantly affect the environment. The report should include an assessment of the project''s impact on the environment, as well as any mitigation measures that will be taken to minimize negative effects. The regulation aims to ensure that development projects are carried out in a sustainable and environmentally responsible manner.', 'The "Bekendtgørelse om vurdering af visse offentlige og private anlægs virkning på miljøet (VVM) i medfør af lov om planlægning" is a regulation in Denmark related to assessing the environmental impact of certain public and private projects. Businesses are required to prepare and submit a VVM report if their project meets certain criteria and has the potential to significantly affect the environment. The report should include an assessment of the project''s impact on the environment, as well as any mitigation measures that will be taken to minimize negative effects. The regulation aims to ensure that development projects are carried out in a sustainable and environmentally responsible manner.', 'The "Bekendtgørelse om vurdering af visse offentlige og private anlægs virkning på miljøet (VVM) i medfør af lov om planlægning" is a regulation in Denmark related to assessing the environmental impact of certain public and private projects. Businesses are required to prepare and submit a VVM report if their project meets certain criteria and has the potential to significantly affect the environment. The report should include an assessment of the project''s impact on the environment, as well as any mitigation measures that will be taken to minimize negative effects. The regulation aims to ensure that development projects are carried out in a sustainable and environmentally responsible manner.', 'Denmark', 'climate', 'in_force', '2016-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_26', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'denmark', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0c23d188-9276-543a-83c5-c95acabcaff5', 'Denmark Executive Order on notification of accidents under the', 'Executive Order on notification of accidents under the Occupational Injuries Insurance Act', 'The "Bekendtgørelse om anmeldelse af ulykker efter arbejdsskadesikringsloven" is a Danish regulation that requires employers to report work-related accidents and injuries to the Danish Working Environment Authority (Arbejdstilsynet). Under this regulation, employers are obligated to report accidents resulting in absence from work for more than one day or in serious injuries, illnesses, or fatalities. The regulation also mandates that employers inform the affected employee or their representatives of their right to file a claim for compensation under the Danish Workers'' Compensation Act.', 'The "Bekendtgørelse om anmeldelse af ulykker efter arbejdsskadesikringsloven" is a Danish regulation that requires employers to report work-related accidents and injuries to the Danish Working Environment Authority (Arbejdstilsynet). Under this regulation, employers are obligated to report accidents resulting in absence from work for more than one day or in serious injuries, illnesses, or fatalities. The regulation also mandates that employers inform the affected employee or their representatives of their right to file a claim for compensation under the Danish Workers'' Compensation Act.', 'The "Bekendtgørelse om anmeldelse af ulykker efter arbejdsskadesikringsloven" is a Danish regulation that requires employers to report work-related accidents and injuries to the Danish Working Environment Authority (Arbejdstilsynet). Under this regulation, employers are obligated to report accidents resulting in absence from work for more than one day or in serious injuries, illnesses, or fatalities. The regulation also mandates