INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5285110a-5d25-5bde-b7b4-e72e59ed007d', 'Denmark Executive Order on control of the risk', 'Executive Order on control of the risk of major accidents with dangerous substances', 'This Executive Order lays down rules on the prevention of major accidents at and around risk companies, including individual facilities and warehouses where dangerous substances may occur, as well as rules on limiting the consequences of major accidents for human health and the environment.', 'This Executive Order lays down rules on the prevention of major accidents at and around risk companies, including individual facilities and warehouses where dangerous substances may occur, as well as rules on limiting the consequences of major accidents for human health and the environment.', 'This Executive Order lays down rules on the prevention of major accidents at and around risk companies, including individual facilities and warehouses where dangerous substances may occur, as well as rules on limiting the consequences of major accidents for human health and the environment.', 'Denmark', 'climate', 'in_force', '2016-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_29', ARRAY['other sustainability policy', 'sdg7', 'mandatory', 'mandatory_regulations', 'denmark', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f17ae317-e209-513b-894e-06c0e1aa3d72', 'Denmark Executive Order on the management of extractive waste', 'Executive Order on the management of extractive waste', 'The "Bekendtgørelse om håndtering af udvindingsaffald" is a Danish regulation on the handling of extractive waste. It places obligations on businesses that extract minerals and metals, as well as businesses that manage extractive waste. The obligations include ensuring that waste is properly classified and treated according to its hazardous properties, and that it is stored and transported safely. The regulation also requires businesses to prepare a waste management plan, report on their waste management activities, and take measures to prevent environmental harm. Additionally, the regulation sets out requirements for the closure and aftercare of waste facilities.', 'The "Bekendtgørelse om håndtering af udvindingsaffald" is a Danish regulation on the handling of extractive waste. It places obligations on businesses that extract minerals and metals, as well as businesses that manage extractive waste. The obligations include ensuring that waste is properly classified and treated according to its hazardous properties, and that it is stored and transported safely. The regulation also requires businesses to prepare a waste management plan, report on their waste management activities, and take measures to prevent environmental harm. Additionally, the regulation sets out requirements for the closure and aftercare of waste facilities.', 'The "Bekendtgørelse om håndtering af udvindingsaffald" is a Danish regulation on the handling of extractive waste. It places obligations on businesses that extract minerals and metals, as well as businesses that manage extractive waste. The obligations include ensuring that waste is properly classified and treated according to its hazardous properties, and that it is stored and transported safely. The regulation also requires businesses to prepare a waste management plan, report on their waste management activities, and take measures to prevent environmental harm. Additionally, the regulation sets out requirements for the closure and aftercare of waste facilities.', 'Denmark', 'climate', 'in_force', '2016-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_30', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'denmark', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fee4b67b-8a56-50c7-bc27-65f32b6abbeb', 'Denmark Executive Order on the publication of a number', 'Executive Order on the publication of a number of statements pursuant to the Danish Financial Statements Act', 'The "Bekendtgørelse om offentliggørelse af en række redegørelser efter årsregnskabsloven" is a regulation in Denmark that governs the disclosure requirements for certain reports under the Annual Accounts Act. The regulation requires businesses to publish reports on their corporate social responsibility, including environmental and social matters, diversity, human rights, and anti-corruption measures. The reports must be published annually, and the regulation specifies the content and format of the reports. The regulation applies to all large companies, including listed companies, and some smaller companies with specific activities or a high level of public interest.', 'The "Bekendtgørelse om offentliggørelse af en række redegørelser efter årsregnskabsloven" is a regulation in Denmark that governs the disclosure requirements for certain reports under the Annual Accounts Act. The regulation requires businesses to publish reports on their corporate social responsibility, including environmental and social matters, diversity, human rights, and anti-corruption measures. The reports must be published annually, and the regulation specifies the content and format of the reports. The regulation applies to all large companies, including listed companies, and some smaller companies with specific activities or a high level of public interest.', 'The "Bekendtgørelse om offentliggørelse af en række redegørelser efter årsregnskabsloven" is a regulation in Denmark that governs the disclosure requirements for certain reports under the Annual Accounts Act. The regulation requires businesses to publish reports on their corporate social responsibility, including environmental and social matters, diversity, human rights, and anti-corruption measures. The reports must be published annually, and the regulation specifies the content and format of the reports. The regulation applies to all large companies, including listed companies, and some smaller companies with specific activities or a high level of public interest.', 'Denmark', 'climate', 'in_force', '2016-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_33', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'denmark', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b235a0ab-d3e9-5722-a36d-a86f0dfc91ff', 'Denmark Stewardship Code The Committee on Corporate Governance', 'Stewardship Code The Committee on Corporate Governance', 'These stewardship principles are “soft law “ to be applied on a “comply or explain” basis. Thus, investors can choose either to comply with a given principle or not, in which case the investor should give an explanation as to why and how the investor has chosen to act in that particular regard. To establish the necessary level of transparency, investors are encouraged to consider the principles and dis- close whether or not they comply with each principle.', 'These stewardship principles are “soft law “ to be applied on a “comply or explain” basis. Thus, investors can choose either to comply with a given principle or not, in which case the investor should give an explanation as to why and how the investor has chosen to act in that particular regard. To establish the necessary level of transparency, investors are encouraged to consider the principles and dis- close whether or not they comply with each principle.', 'These stewardship principles are “soft law “ to be applied on a “comply or explain” basis. Thus, investors can choose either to comply with a given principle or not, in which case the investor should give an explanation as to why and how the investor has chosen to act in that particular regard. To establish the necessary level of transparency, investors are encouraged to consider the principles and dis- close whether or not they comply with each principle.', 'Denmark', 'governance', 'in_force', '2016-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_7', ARRAY['regulations', 'mandatory', 'sdg16', 'denmark', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('71fc972b-ae65-5def-98bd-7ca48eca18d6', 'Denmark Act amending the Annual Accounts Act and various', 'Act amending the Annual Accounts Act and various other acts', 'The 2015 law on the amendment of the Annual Accounts Act and various other laws in Denmark primarily focused on enhancing transparency and accountability in the financial reporting of businesses. The law requires companies to disclose information related to their ownership, governance, and financial performance, including their corporate social responsibility policies, gender diversity on boards, and executive remuneration. The law also mandates that companies prepare their financial statements in accordance with International Financial Reporting Standards (IFRS) and adopt digital financial reporting in their annual reports. Furthermore, the law strengthens the audit committees'' role in companies and enhances their independence, ensuring that auditors carry out their duties effectively and efficiently.', 'The 2015 law on the amendment of the Annual Accounts Act and various other laws in Denmark primarily focused on enhancing transparency and accountability in the financial reporting of businesses. The law requires companies to disclose information related to their ownership, governance, and financial performance, including their corporate social responsibility policies, gender diversity on boards, and executive remuneration. The law also mandates that companies prepare their financial statements in accordance with International Financial Reporting Standards (IFRS) and adopt digital financial reporting in their annual reports. Furthermore, the law strengthens the audit committees'' role in companies and enhances their independence, ensuring that auditors carry out their duties effectively and efficiently.', 'The 2015 law on the amendment of the Annual Accounts Act and various other laws in Denmark primarily focused on enhancing transparency and accountability in the financial reporting of businesses. The law requires companies to disclose information related to their ownership, governance, and financial performance, including their corporate social responsibility policies, gender diversity on boards, and executive remuneration. The law also mandates that companies prepare their financial statements in accordance with International Financial Reporting Standards (IFRS) and adopt digital financial reporting in their annual reports. Furthermore, the law strengthens the audit committees'' role in companies and enhances their independence, ensuring that auditors carry out their duties effectively and efficiently.', 'Denmark', 'climate', 'in_force', '2015-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_20', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg5', 'sdg16', 'denmark', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f8283b1a-5a5f-5f44-9adb-bdee421ac39d', 'Denmark Promulgation of the Offshore Safety Act', 'Promulgation of the Offshore Safety Act', 'The "Bekendtgørelse af offshoresikkerhedsloven" is the Danish executive order that provides guidelines for offshore safety in the oil and gas industry. The order places obligations on businesses that operate in the offshore sector to ensure the safety of their workers and to prevent accidents, including establishing safety management systems, conducting risk assessments, providing training, and reporting incidents. The order also requires businesses to comply with national and international safety standards, maintain safety equipment and facilities, and provide adequate emergency response measures.', 'The "Bekendtgørelse af offshoresikkerhedsloven" is the Danish executive order that provides guidelines for offshore safety in the oil and gas industry. The order places obligations on businesses that operate in the offshore sector to ensure the safety of their workers and to prevent accidents, including establishing safety management systems, conducting risk assessments, providing training, and reporting incidents. The order also requires businesses to comply with national and international safety standards, maintain safety equipment and facilities, and provide adequate emergency response measures.', 'The "Bekendtgørelse af offshoresikkerhedsloven" is the Danish executive order that provides guidelines for offshore safety in the oil and gas industry. The order places obligations on businesses that operate in the offshore sector to ensure the safety of their workers and to prevent accidents, including establishing safety management systems, conducting risk assessments, providing training, and reporting incidents. The order also requires businesses to comply with national and international safety standards, maintain safety equipment and facilities, and provide adequate emergency response measures.', 'Denmark', 'climate', 'in_force', '2015-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_21', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'denmark', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00671e42-729c-5014-aaae-9abf437d7925', 'Denmark Executive Order of the Danish Financial Statements Act', 'Executive Order of the Danish Financial Statements Act', 'The Bekendtgørelse af årsregnskabsloven is a Danish regulation that outlines the requirements for annual financial reporting of companies. The regulation applies to all companies in Denmark, regardless of size and type. The obligations of businesses under the regulation include preparing and submitting annual financial statements, including a balance sheet, an income statement, a cash flow statement, and notes to the financial statements. The financial statements must be prepared in accordance with Danish accounting principles and must provide a true and fair view of the company''s financial position, performance, and cash flows. The regulation also requires companies to prepare a management report, which should provide an analysis of the company''s operations and financial performance, as well as a description of the company''s risk management policies and other key management practices. Companies must also have their financial statements audited by a registered auditor, who will issue an auditor''s report.', 'The Bekendtgørelse af årsregnskabsloven is a Danish regulation that outlines the requirements for annual financial reporting of companies. The regulation applies to all companies in Denmark, regardless of size and type. The obligations of businesses under the regulation include preparing and submitting annual financial statements, including a balance sheet, an income statement, a cash flow statement, and notes to the financial statements. The financial statements must be prepared in accordance with Danish accounting principles and must provide a true and fair view of the company''s financial position, performance, and cash flows. The regulation also requires companies to prepare a management report, which should provide an analysis of the company''s operations and financial performance, as well as a description of the company''s risk management policies and other key management practices. Companies must also have their financial statements audited by a registered auditor, who will issue an auditor''s report.', 'The Bekendtgørelse af årsregnskabsloven is a Danish regulation that outlines the requirements for annual financial reporting of companies. The regulation applies to all companies in Denmark, regardless of size and type. The obligations of businesses under the regulation include preparing and submitting annual financial statements, including a balance sheet, an income statement, a cash flow statement, and notes to the financial statements. The financial statements must be prepared in accordance with Danish accounting principles and must provide a true and fair view of the company''s financial position, performance, and cash flows. The regulation also requires companies to prepare a management report, which should provide an analysis of the company''s operations and financial performance, as well as a description of the company''s risk management policies and other key management practices. Companies must also have their financial statements audited by a registered auditor, who will issue an auditor''s report.', 'Denmark', 'climate', 'in_force', '2015-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_23', ARRAY['other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'denmark', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1fa0a15-c599-5cbd-935a-cd87bfe268f5', 'Denmark Executive Order on a register of emissions', 'Executive Order on a register of emissions and transmissions of pollutants (PRTR)', 'The Bekendtgørelse (Announcement) of Denmark in 2015 established a register of pollution emissions and transfers known as the Pollutant Release and Transfer Register (PRTR). The regulation requires businesses in certain industries to report their emissions and transfers of specified pollutants to the PRTR annually. The data collected in the register is made available to the public to promote transparency and to inform decision-making related to environmental policy. The businesses obligated to report include those in the manufacturing, energy, waste management, and mining sectors, among others.', 'The Bekendtgørelse (Announcement) of Denmark in 2015 established a register of pollution emissions and transfers known as the Pollutant Release and Transfer Register (PRTR). The regulation requires businesses in certain industries to report their emissions and transfers of specified pollutants to the PRTR annually. The data collected in the register is made available to the public to promote transparency and to inform decision-making related to environmental policy. The businesses obligated to report include those in the manufacturing, energy, waste management, and mining sectors, among others.', 'The Bekendtgørelse (Announcement) of Denmark in 2015 established a register of pollution emissions and transfers known as the Pollutant Release and Transfer Register (PRTR). The regulation requires businesses in certain industries to report their emissions and transfers of specified pollutants to the PRTR annually. The data collected in the register is made available to the public to promote transparency and to inform decision-making related to environmental policy. The businesses obligated to report include those in the manufacturing, energy, waste management, and mining sectors, among others.', 'Denmark', 'climate', 'in_force', '2015-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_24', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'denmark', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf1ad4d5-07c5-5b6e-b8be-0328c3122445', 'Denmark Danish National Action Plan – implementation of the', 'Danish National Action Plan – implementation of the UN Guiding Principles on Business and Human Rights', 'The Plan is focused on preventing and mitigating adverse impacts on human rights by Danish companies at home and abroad, seeking to be a global front runner. It assist private and public businesses in turning the respect for Human Rights into reality wherever they operate and aims to strengthen the existing legal reporting requirement for the largest Danish companies and all state-owned companies.', 'The Plan is focused on preventing and mitigating adverse impacts on human rights by Danish companies at home and abroad, seeking to be a global front runner. It assist private and public businesses in turning the respect for Human Rights into reality wherever they operate and aims to strengthen the existing legal reporting requirement for the largest Danish companies and all state-owned companies.', 'The Plan is focused on preventing and mitigating adverse impacts on human rights by Danish companies at home and abroad, seeking to be a global front runner. It assist private and public businesses in turning the respect for Human Rights into reality wherever they operate and aims to strengthen the existing legal reporting requirement for the largest Danish companies and all state-owned companies.', 'Denmark', 'climate', 'in_force', '2014-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_3', ARRAY['other sustainability policy', 'regulations', 'sdg17', 'sdg16', 'denmark', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('05021b61-614b-520f-b8db-e2ed157df91c', 'Denmark Recommendations on Corporate Governance', 'Recommendations on Corporate Governance, 2013', 'Recommendations by the Committee are best practice guidelines for the management of companies admitted to trading on a regulated market, including NASDAQ OMX Copenhagen A/S. The basic philosophy is that it should be attractive to invest in companies. Corporate governance inspiring economic value creation makes it easier for companies to acquire capital. The Committee will monitor developments in corporate governance to continuously develop the recommendations to comply with the soft law principle. Developments show that there is no longer a need for explicit recommendations in certain areas, but this does not imply that the principles are no longer of value.', 'Recommendations by the Committee are best practice guidelines for the management of companies admitted to trading on a regulated market, including NASDAQ OMX Copenhagen A/S. The basic philosophy is that it should be attractive to invest in companies. Corporate governance inspiring economic value creation makes it easier for companies to acquire capital. The Committee will monitor developments in corporate governance to continuously develop the recommendations to comply with the soft law principle. Developments show that there is no longer a need for explicit recommendations in certain areas, but this does not imply that the principles are no longer of value.', 'Recommendations by the Committee are best practice guidelines for the management of companies admitted to trading on a regulated market, including NASDAQ OMX Copenhagen A/S. The basic philosophy is that it should be attractive to invest in companies. Corporate governance inspiring economic value creation makes it easier for companies to acquire capital. The Committee will monitor developments in corporate governance to continuously develop the recommendations to comply with the soft law principle. Developments show that there is no longer a need for explicit recommendations in certain areas, but this does not imply that the principles are no longer of value.', 'Denmark', 'governance', 'in_force', '2013-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_13', ARRAY['guidance_frameworks', 'sdg16', 'denmark', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bea4c682-7e47-5359-8d7c-2a9073661f65', 'Denmark Recommendations on Corporate Governance', 'Recommendations on Corporate Governance 2013', 'The purpose of corporate governance is to support value creation and accountable management, and thus to contribute to the long-term success of companies. These recommendations aim to ensure confidence in companies through the provision of timely information as well as transparency.', 'The purpose of corporate governance is to support value creation and accountable management, and thus to contribute to the long-term success of companies. These recommendations aim to ensure confidence in companies through the provision of timely information as well as transparency.', 'The purpose of corporate governance is to support value creation and accountable management, and thus to contribute to the long-term success of companies. These recommendations aim to ensure confidence in companies through the provision of timely information as well as transparency.', 'Denmark', 'climate', 'in_force', '2013-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_2', ARRAY['guidance_frameworks', 'sdg16', 'denmark', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d545e17f-f40b-547f-8f54-1da55d7a6ca2', 'Denmark Responsible growth: Action Plan for Corporate Social Responsibility', 'Responsible growth: Action Plan for Corporate Social Responsibility 2012-2015', 'This action plan does not only look at the companies and their business interests in implementing social responsibility. It is the Government’s ambition that both human and natural resources in Denmark should be used in a way that is both sustainable and competitive. This applies nationally as well as internationally. Social responsibility is therefore about ensuring that growth and responsibility go hand in hand, creating shared value for both companies and society. This task involves the Danish business sector, the public sector, as well as civil society.', 'This action plan does not only look at the companies and their business interests in implementing social responsibility. It is the Government’s ambition that both human and natural resources in Denmark should be used in a way that is both sustainable and competitive. This applies nationally as well as internationally. Social responsibility is therefore about ensuring that growth and responsibility go hand in hand, creating shared value for both companies and society. This task involves the Danish business sector, the public sector, as well as civil society.', 'This action plan does not only look at the companies and their business interests in implementing social responsibility. It is the Government’s ambition that both human and natural resources in Denmark should be used in a way that is both sustainable and competitive. This applies nationally as well as internationally. Social responsibility is therefore about ensuring that growth and responsibility go hand in hand, creating shared value for both companies and society. This task involves the Danish business sector, the public sector, as well as civil society.', 'Denmark', 'climate', 'in_force', '2012-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_1', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'sdg16', 'denmark']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ad6c4643-22b1-5f7b-9c11-6d8edc8e4e79', 'Denmark CO2 quotas law', 'CO2 quotas law', 'The Danish 2012 "Act on CO2 Quotas" is aimed at reducing greenhouse gas emissions and obligates businesses that operate in Denmark and are included in the EU Emissions Trading System (ETS) to hold CO2 quotas equal to their annual emissions of greenhouse gases. These businesses must also monitor and report their emissions to the Danish Environmental Protection Agency, which will verify compliance with the quota requirement. In case of non-compliance, businesses may face fines and penalties. The Act also provides for the creation of a CO2 emissions registry for tracking and trading quotas.', 'The Danish 2012 "Act on CO2 Quotas" is aimed at reducing greenhouse gas emissions and obligates businesses that operate in Denmark and are included in the EU Emissions Trading System (ETS) to hold CO2 quotas equal to their annual emissions of greenhouse gases. These businesses must also monitor and report their emissions to the Danish Environmental Protection Agency, which will verify compliance with the quota requirement. In case of non-compliance, businesses may face fines and penalties. The Act also provides for the creation of a CO2 emissions registry for tracking and trading quotas.', 'The Danish 2012 "Act on CO2 Quotas" is aimed at reducing greenhouse gas emissions and obligates businesses that operate in Denmark and are included in the EU Emissions Trading System (ETS) to hold CO2 quotas equal to their annual emissions of greenhouse gases. These businesses must also monitor and report their emissions to the Danish Environmental Protection Agency, which will verify compliance with the quota requirement. In case of non-compliance, businesses may face fines and penalties. The Act also provides for the creation of a CO2 emissions registry for tracking and trading quotas.', 'Denmark', 'climate', 'in_force', '2012-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_22', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'denmark', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c23835ee-4d4e-5850-bef8-3b740f5627bc', 'Denmark waste', 'Order on waste', 'The "Bekendtgørelse om affald" is a Danish regulation on waste management, last updated in 2012. The regulation outlines the obligations of businesses in relation to waste management, including requirements for waste sorting, storage, transport, and disposal. Businesses are required to have a waste management plan and register, and are responsible for ensuring that their waste is handled in an environmentally responsible manner. The regulation also establishes guidelines for hazardous waste management and sets limits for the amount of certain hazardous substances that can be released into the environment.', 'The "Bekendtgørelse om affald" is a Danish regulation on waste management, last updated in 2012. The regulation outlines the obligations of businesses in relation to waste management, including requirements for waste sorting, storage, transport, and disposal. Businesses are required to have a waste management plan and register, and are responsible for ensuring that their waste is handled in an environmentally responsible manner. The regulation also establishes guidelines for hazardous waste management and sets limits for the amount of certain hazardous substances that can be released into the environment.', 'The "Bekendtgørelse om affald" is a Danish regulation on waste management, last updated in 2012. The regulation outlines the obligations of businesses in relation to waste management, including requirements for waste sorting, storage, transport, and disposal. Businesses are required to have a waste management plan and register, and are responsible for ensuring that their waste is handled in an environmentally responsible manner. The regulation also establishes guidelines for hazardous waste management and sets limits for the amount of certain hazardous substances that can be released into the environment.', 'Denmark', 'climate', 'in_force', '2012-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_25', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'denmark', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3c6f738-4167-505b-9705-a1e460606865', 'Denmark Executive Order on assessment of impact on the', 'Executive Order on assessment of impact on the environment (EIA) for projects on establishment etc. of electricity generation plants at sea', 'This executive order concerns the assessment of the impacts on the environment (EIA) in connection with projects mentioned in § 2, para. 1, in the territorial sea and in the exclusive economic zone.', 'This executive order concerns the assessment of the impacts on the environment (EIA) in connection with projects mentioned in § 2, para. 1, in the territorial sea and in the exclusive economic zone.', 'This executive order concerns the assessment of the impacts on the environment (EIA) in connection with projects mentioned in § 2, para. 1, in the territorial sea and in the exclusive economic zone.', 'Denmark', 'climate', 'in_force', '2012-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_31', ARRAY['sdg13', 'sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'denmark']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4939db0b-c755-5fb5-92a9-45dcb44323fb', 'Denmark Recommendations on Corporate Governance', 'Recommendations on Corporate Governance, 2011', 'The Committee’s recommendations are aimed primarily at Danish companies whose shares are admitted to trading on a regulated market. The Committee’s objective is that the recommendations are appropriate for such companies and comply with Danish and EU company law etc., OECD’s Principles of Corporate Governance and recognised best practice.', 'The Committee’s recommendations are aimed primarily at Danish companies whose shares are admitted to trading on a regulated market. The Committee’s objective is that the recommendations are appropriate for such companies and comply with Danish and EU company law etc., OECD’s Principles of Corporate Governance and recognised best practice.', 'The Committee’s recommendations are aimed primarily at Danish companies whose shares are admitted to trading on a regulated market. The Committee’s objective is that the recommendations are appropriate for such companies and comply with Danish and EU company law etc., OECD’s Principles of Corporate Governance and recognised best practice.', 'Denmark', 'governance', 'in_force', '2011-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_14', ARRAY['guidance_frameworks', 'sdg16', 'denmark', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
