INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1092127-df0b-55d9-a8a4-37bc75843bb5', 'Denmark Recommendations for corporate governance of August 15, 2005', 'Recommendations for corporate governance of August 15, 2005 sections III and V revised by December 10, 2008', 'The recommendations are divided into eight main areas. Each main area begins with the general rationale that describes the reason why the topic is subject to Recommendations. Then follow the actual Recommendations proposed by the Committee on the basis of the rationale. Finally, the Recommendations include comments on a varying degree. These comments are in effect not part of the Recommendations, however, they convey practical instructions and examples of how the companies may apply the Recommendations.', 'The recommendations are divided into eight main areas. Each main area begins with the general rationale that describes the reason why the topic is subject to Recommendations. Then follow the actual Recommendations proposed by the Committee on the basis of the rationale. Finally, the Recommendations include comments on a varying degree. These comments are in effect not part of the Recommendations, however, they convey practical instructions and examples of how the companies may apply the Recommendations.', 'The recommendations are divided into eight main areas. Each main area begins with the general rationale that describes the reason why the topic is subject to Recommendations. Then follow the actual Recommendations proposed by the Committee on the basis of the rationale. Finally, the Recommendations include comments on a varying degree. These comments are in effect not part of the Recommendations, however, they convey practical instructions and examples of how the companies may apply the Recommendations.', 'Denmark', 'climate', 'in_force', '2008-01-01'::date, 'Denmark', 'https