INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4f4cbce9-a60d-50a2-8e25-667f306669bc', 'Denmark Active ownership and transparency in private equity funds', 'Active ownership and transparency in private equity funds: Guidelines for responsible ownership and good corporate governance', 'The aim of these guidelines is to bring about the necessary transparency and information from private equity funds and the companies they own. Beyond this, the guidelines do not themselves make recommendations as to how ownership of portfolio companies is to be administered. However, DVCA advises its member companies to formulate guidelines for social responsibility in their investment policy. Because the investors behind private equity funds have very often al- ready formulated such guidelines themselves, the development of guidelines for social responsibility can usefully be performed in collaboration with investors.', 'The aim of these guidelines is to bring about the necessary transparency and information from private equity funds and the companies they own. Beyond this, the guidelines do not themselves make recommendations as to how ownership of portfolio companies is to be administered. However, DVCA advises its member companies to formulate guidelines for social responsibility in their investment policy. Because the investors behind private equity funds have very often al- ready formulated such guidelines themselves, the development of guidelines for social responsibility can usefully be performed in collaboration with investors.', 'The aim of these guidelines is to bring about the necessary transparency and information from private equity funds and the companies they own. Beyond this, the guidelines do not themselves make recommendations as to how ownership of portfolio companies is to be administered. However, DVCA advises its member companies to formulate guidelines for social responsibility in their investment policy. Because the investors behind private equity funds have very often al- ready formulated such guidelines themselves, the development of guidelines for social responsibility can usefully be performed in collaboration with investors.', 'Denmark', 'climate', 'in_force', '2008-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_6', ARRAY['regulations', 'sdg17', 'sdg16', 'denmark', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ddcd4ab9-12c1-5a10-bd2d-5749297501da', 'Denmark Amendment Of The Danish Financial Statements Act', 'Law On The Amendment Of The Danish Financial Statements Act', 'This Act required reporting on intellectual capital resources and environmental aspects in the management report, if it is material to providing a true and fair view of the company''s financial position.', 'This Act required reporting on intellectual capital resources and environmental aspects in the management report, if it is material to providing a true and fair view of the company''s financial position.', 'This Act required reporting on intellectual capital resources and environmental aspects in the management report, if it is material to providing a true and fair view of the company''s financial position.', 'Denmark', 'climate', 'in_force', '2007-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_5', ARRAY['mandatory', 'denmark', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
