INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f642f0be-3f76-57b6-ad36-924b9e44c071', 'Report on Corporate Governance in Denmark', 'Report on Corporate Governance in Denmark, 2003', 'The Copenhagen Stock Exchange recommends listed companies to address the Nørby Committee''s recommendations for corporate governance in their annual reports. Denmark joined the large group of countries with a voluntary (i.e. not legally binding) code of conduct for what may be regarded as corporate governance. In order to ensure a continuation of the work carried out, the Copenhagen Stock Ex- change appointed an independent corporate governance committee.', 'The Copenhagen Stock Exchange recommends listed companies to address the Nørby Committee''s recommendations for corporate governance in their annual reports. Denmark joined the large group of countries with a voluntary (i.e. not legally binding) code of conduct for what may be regarded as corporate governance. In order to ensure a continuation of the work carried out, the Copenhagen Stock Ex- change appointed an independent corporate governance committee.', 'The Copenhagen Stock Exchange recommends listed companies to address the Nørby Committee''s recommendations for corporate governance in their annual reports. Denmark joined the large group of countries with a voluntary (i.e. not legally binding) code of conduct for what may be regarded as corporate governance. In order to ensure a continuation of the work carried out, the Copenhagen Stock Ex- change appointed an independent corporate governance committee.', 'Denmark', 'climate', 'in_force', '2003-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_15', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'denmark', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b288e9f9-2944-59ba-a3e9-3c1a003924b2', 'Denmark Executive Order on facilities that incinerate waste', 'Executive Order on facilities that incinerate waste', 'The "Bekendtgørelse om anlæg, der forbrænder affald" is a Danish regulation from 2003 that concerns waste incineration plants. The regulation sets requirements for these plants, including limits on emissions of pollutants and requirements for monitoring and reporting of emissions. It also requires waste incineration plants to obtain an environmental permit and to comply with certain technical requirements. The regulation places obligations on both the operator of the plant and the relevant authorities responsible for enforcing the regulation.', 'The "Bekendtgørelse om anlæg, der forbrænder affald" is a Danish regulation from 2003 that concerns waste incineration plants. The regulation sets requirements for these plants, including limits on emissions of pollutants and requirements for monitoring and reporting of emissions. It also requires waste incineration plants to obtain an environmental permit and to comply with certain technical requirements. The regulation places obligations on both the operator of the plant and the relevant authorities responsible for enforcing the regulation.', 'The "Bekendtgørelse om anlæg, der forbrænder affald" is a Danish regulation from 2003 that concerns waste incineration plants. The regulation sets requirements for these plants, including limits on emissions of pollutants and requirements for monitoring and reporting of emissions. It also requires waste incineration plants to obtain an environmental permit and to comply with certain technical requirements. The regulation places obligations on both the operator of the plant and the relevant authorities responsible for enforcing the regulation.', 'Denmark', 'climate', 'in_force', '2003-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_27', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'denmark', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e745d070-7c58-5a54-aaa6-b595e3ad142e', 'Denmark limitation of certain air pollutants emissions from large', 'Order on the limitation of certain air pollutants emissions from large combustion plants', 'The "Bekendtgørelse om begrænsning af visse luftforurenende emissioner fra store fyringsanlæg" is a Danish regulation from 2003 that aims to limit certain air pollutants emitted from large combustion plants. The obligations of businesses include obtaining permits for operating such plants, meeting specific emission limit values, performing regular monitoring and reporting of emissions, and maintaining records of compliance with the regulation. Businesses must also implement measures to reduce emissions and report any deviations from the requirements to the authorities.', 'The "Bekendtgørelse om begrænsning af visse luftforurenende emissioner fra store fyringsanlæg" is a Danish regulation from 2003 that aims to limit certain air pollutants emitted from large combustion plants. The obligations of businesses include obtaining permits for operating such plants, meeting specific emission limit values, performing regular monitoring and reporting of emissions, and maintaining records of compliance with the regulation. Businesses must also implement measures to reduce emissions and report any deviations from the requirements to the authorities.', 'The "Bekendtgørelse om begrænsning af visse luftforurenende emissioner fra store fyringsanlæg" is a Danish regulation from 2003 that aims to limit certain air pollutants emitted from large combustion plants. The obligations of businesses include obtaining permits for operating such plants, meeting specific emission limit values, performing regular monitoring and reporting of emissions, and maintaining records of compliance with the regulation. Businesses must also implement measures to reduce emissions and report any deviations from the requirements to the authorities.', 'Denmark', 'climate', 'in_force', '2003-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_32', ARRAY['sdg13', 'other sustainability policy', 'sdg7', 'mandatory', 'mandatory_regulations', 'denmark', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ff41910e-fe52-563e-94a0-00548de19c25', 'Corporate Governance in Denmark - The Nørby Committees report', 'Corporate Governance in Denmark - The Nørby Committees report, 2001', 'There are several objectives in preparing recommendations for good corporate governance: (1) to make it more attractive to invest in Danish listed companies and to improve Danish companies’ access to funds by attracting foreign investments among others. (2) To inspire Danish companies as well as their directors and managers to tackle the strategic challenges resulting from the globalisation, and in so doing, strengthen the companies’ competitiveness. (3) To promote good corporate governance in Danish companies by stimulating the debate about corporate governance.  Apart from the stated objectives the recommendations will hopefully be able to support the changed Danish share culture, which has led to even more individuals owning shares, by creating increased confidence in the companies. In addition to this, an increased focus on the managements of the company and their work may very well mean that the quality of the managements’ work is lifted in general.', 'There are several objectives in preparing recommendations for good corporate governance: (1) to make it more attractive to invest in Danish listed companies and to improve Danish companies’ access to funds by attracting foreign investments among others. (2) To inspire Danish companies as well as their directors and managers to tackle the strategic challenges resulting from the globalisation, and in so doing, strengthen the companies’ competitiveness. (3) To promote good corporate governance in Danish companies by stimulating the debate about corporate governance.  Apart from the stated objectives the recommendations will hopefully be able to support the changed Danish share culture, which has led to even more individuals owning shares, by creating increased confidence in the companies. In addition to this, an increased focus on the managements of the company and their work may very well mean that the quality of the managements’ work is lifted in general.', 'There are several objectives in preparing recommendations for good corporate governance: (1) to make it more attractive to invest in Danish listed companies and to improve Danish companies’ access to funds by attracting foreign investments among others. (2) To inspire Danish companies as well as their directors and managers to tackle the strategic challenges resulting from the globalisation, and in so doing, strengthen the companies’ competitiveness. (3) To promote good corporate governance in Danish companies by stimulating the debate about corporate governance.  Apart from the stated objectives the recommendations will hopefully be able to support the changed Danish share culture, which has led to even more individuals owning shares, by creating increased confidence in the companies. In addition to this, an increased focus on the managements of the company and their work may very well mean that the quality of the managements’ work is lifted in general.', 'Denmark', 'climate', 'in_force', '2001-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_17', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'denmark']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6ee61367-6273-58dd-94bf-7ab537be4333', 'Denmark Danish Financial Statements Act', 'The Danish Financial Statements Act', 'This Act required reporting on intellectual capital resources and environmental aspects in the management report, if it is material to providing a true and fair view of the company''s financial position.', 'This Act required reporting on intellectual capital resources and environmental aspects in the management report, if it is material to providing a true and fair view of the company''s financial position.', 'This Act required reporting on intellectual capital resources and environmental aspects in the management report, if it is material to providing a true and fair view of the company''s financial position.', 'Denmark', 'climate', 'in_force', '2001-01-01'::date, 'Denmark', 'https://www.carrotsandsticks.org/policies/43_4', ARRAY['mandatory', 'other sustainability policy', 'denmark', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('254c3323-ae34-570a-a75e-6455a1d722ca', 'Dominican Republic Environmental Standard for the Control of Atmospheric', 'Environmental Standard for the Control of Atmospheric Pollutant Emissions from Fixed Sources', 'The objective of this Code is to establish the maximum permissible limits of emissions to the atmosphere from stationary sources to reduce air pollution levels.', 'The objective of this Code is to establish the maximum permissible limits of emissions to the atmosphere from stationary sources to reduce air pollution levels.', 'The objective of this Code is to establish the maximum permissible limits of emissions to the atmosphere from stationary sources to reduce air pollution levels.', 'Dominican Republic', 'climate', 'in_force', '2017-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_6', ARRAY['sdg13', 'sdg7', 'voluntary', 'dominican republic', 'sdg12', 'disclosure', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0a980a2c-0a2e-5242-bb47-5458318cd4b6', 'Dominican Republic Dec. establishing the Hydrocarbons Exploration and Production', 'Dec. No. 83-16 establishing the Hydrocarbons Exploration and Production Regulation. OG No. 10832 of March 7, 2016', 'The purpose of this Regulation is to promote, develop, regulate, regulate and control the exploration and exploitation of hydrocarbon deposits and any other hydrocarbon substances, regardless of their physical state, preserving and protecting the environment. environment, guaranteeing the interests of the State and the Dominican Nation.', 'The purpose of this Regulation is to promote, develop, regulate, regulate and control the exploration and exploitation of hydrocarbon deposits and any other hydrocarbon substances, regardless of their physical state, preserving and protecting the environment. environment, guaranteeing the interests of the State and the Dominican Nation.', 'The purpose of this Regulation is to promote, develop, regulate, regulate and control the exploration and exploitation of hydrocarbon deposits and any other hydrocarbon substances, regardless of their physical state, preserving and protecting the environment. environment, guaranteeing the interests of the State and the Dominican Nation.', 'Dominican Republic', 'climate', 'in_force', '2016-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_4', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'dominican republic', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d98c7728-c74e-57ee-a0d7-b8e9546ffd0a', 'Dominican Republic Biosafety. OG', 'Law No. 219-15 on Biosafety. OG No. 10815', 'The purpose of this law is to establish the general precepts that regulate the introduction, research, testing, development, handling, transportation, transit, storage, production, marketing, import, export, use and release into the environment, elimination and final disposal of living modified organisms and their derivatives; to guarantee, through biosafety, the safe use of modern biotechnology, helping to achieve an adequate level of protection for the use of living modified organisms and their derivatives and to prevent and control the adverse effects that they may cause on biodiversity, human health and the environment in general.', 'The purpose of this law is to establish the general precepts that regulate the introduction, research, testing, development, handling, transportation, transit, storage, production, marketing, import, export, use and release into the environment, elimination and final disposal of living modified organisms and their derivatives; to guarantee, through biosafety, the safe use of modern biotechnology, helping to achieve an adequate level of protection for the use of living modified organisms and their derivatives and to prevent and control the adverse effects that they may cause on biodiversity, human health and the environment in general.', 'The purpose of this law is to establish the general precepts that regulate the introduction, research, testing, development, handling, transportation, transit, storage, production, marketing, import, export, use and release into the environment, elimination and final disposal of living modified organisms and their derivatives; to guarantee, through biosafety, the safe use of modern biotechnology, helping to achieve an adequate level of protection for the use of living modified organisms and their derivatives and to prevent and control the adverse effects that they may cause on biodiversity, human health and the environment in general.', 'Dominican Republic', 'climate', 'in_force', '2015-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_10', ARRAY['sdg2', 'sdg14', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'dominican republic', 'sdg12', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a50ed4e3-994b-58f6-b330-cb37bb406ad4', 'Dominican Republic General law of comprehensive management and co-processing', 'General law of comprehensive management and co-processing of waste in the Dominican Republic.', 'The purpose of this law is to prevent the generation of waste, in addition to establishing the legal regime for its comprehensive management to promote reduction, reuse, recycling, use and recovery, as well as regulate collection, transportation and sweeping systems; final disposal sites, transfer stations, collection centers and recovery plants; in order to guarantee the right of every person to live in a healthy environment, protect the health of the population, as well as reduce the generation of greenhouse gases emitted by waste.', 'The purpose of this law is to prevent the generation of waste, in addition to establishing the legal regime for its comprehensive management to promote reduction, reuse, recycling, use and recovery, as well as regulate collection, transportation and sweeping systems; final disposal sites, transfer stations, collection centers and recovery plants; in order to guarantee the right of every person to live in a healthy environment, protect the health of the population, as well as reduce the generation of greenhouse gases emitted by waste.', 'The purpose of this law is to prevent the generation of waste, in addition to establishing the legal regime for its comprehensive management to promote reduction, reuse, recycling, use and recovery, as well as regulate collection, transportation and sweeping systems; final disposal sites, transfer stations, collection centers and recovery plants; in order to guarantee the right of every person to live in a healthy environment, protect the health of the population, as well as reduce the generation of greenhouse gases emitted by waste.', 'Dominican Republic', 'climate', 'in_force', '2011-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_9', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'dominican republic', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a057024b-58ab-5d9d-80b3-29dd8e259354', 'Dominican Republic General Law of Commercial Companies and Individual', 'General Law of Commercial Companies and Individual Limited Liability Companies, No. 47908', 'This Law states that commercial companies shall be governed by the provisions of this law, the agreements of the parties, commercial uses and common law.', 'This Law states that commercial companies shall be governed by the provisions of this law, the agreements of the parties, commercial uses and common law.', 'This Law states that commercial companies shall be governed by the provisions of this law, the agreements of the parties, commercial uses and common law.', 'Dominican Republic', 'governance', 'in_force', '2008-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_11', ARRAY['regulations', 'mandatory', 'dominican republic', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1edc0d95-9734-5d7c-9df4-38ccecf93743', 'Dominican Republic Regulation of the System of Environmental Permits', 'Regulation of the System of Environmental Permits and Licenses', 'This regulation aims to regulate the System of Environmental Permits and Licenses established by the General Law on the Environment and Natural Resources, Law 64-00.', 'This regulation aims to regulate the System of Environmental Permits and Licenses established by the General Law on the Environment and Natural Resources, Law 64-00.', 'This regulation aims to regulate the System of Environmental Permits and Licenses established by the General Law on the Environment and Natural Resources, Law 64-00.', 'Dominican Republic', 'governance', 'in_force', '2002-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_16', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'dominican republic', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e32b8dd1-d5e2-5f2f-8ffb-0ddca76ec2ae', 'Dominican Republic Water Quality and Discharge Control AG-CC-01', 'Standard for Water Quality and Discharge Control AG-CC-01', 'This is the first technical standard on wastewater drawn up by the Secretary of State for the Environment and Natural Resources. It establishes classifications of superficial and coastal waters according to their preponderant uses.', 'This is the first technical standard on wastewater drawn up by the Secretary of State for the Environment and Natural Resources. It establishes classifications of superficial and coastal waters according to their preponderant uses.', 'This is the first technical standard on wastewater drawn up by the Secretary of State for the Environment and Natural Resources. It establishes classifications of superficial and coastal waters according to their preponderant uses.', 'Dominican Republic', 'nature', 'in_force', '2001-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_7', ARRAY['sdg14', 'other sustainability policy', 'sdg11', 'sdg6', 'dominican republic', 'voluntary', 'sdg12', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9ccd529-8137-567c-b9cf-348a9d26b1aa', 'Dominican Republic General Law on the Environment and Natural', 'General Law on the Environment and Natural Resources', 'The purpose of this law is to establish the norms for the conservation, protection, improvement and restoration of the environment and natural resources, ensuring its sustainable use.', 'The purpose of this law is to establish the norms for the conservation, protection, improvement and restoration of the environment and natural resources, ensuring its sustainable use.', 'The purpose of this law is to establish the norms for the conservation, protection, improvement and restoration of the environment and natural resources, ensuring its sustainable use.', 'Dominican Republic', 'climate', 'in_force', '2000-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_12', ARRAY['sdg2', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'dominican republic', 'sdg12', 'disclosure', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ce0b0853-f062-5107-85aa-8d07819d9250', 'Dominican Republic Decree 356-99', 'Decree 356-99', 'The Governmental Ozone Committee (COGO) is created to execute the Program for the Reduction of the Consumption of Substances that Deplete the Ozone Layer of the Dominican Republic. This Committee will have its headquarters in the Secretary of State for Agriculture, as the focal point for managing the protection of the ozone layer, and will also be made up of the Secretary of State for Industry and Commerce, the National Office of Meteorology, the National Institute of Environmental Protection and the General Directorate of Customs.', 'The Governmental Ozone Committee (COGO) is created to execute the Program for the Reduction of the Consumption of Substances that Deplete the Ozone Layer of the Dominican Republic. This Committee will have its headquarters in the Secretary of State for Agriculture, as the focal point for managing the protection of the ozone layer, and will also be made up of the Secretary of State for Industry and Commerce, the National Office of Meteorology, the National Institute of Environmental Protection and the General Directorate of Customs.', 'The Governmental Ozone Committee (COGO) is created to execute the Program for the Reduction of the Consumption of Substances that Deplete the Ozone Layer of the Dominican Republic. This Committee will have its headquarters in the Secretary of State for Agriculture, as the focal point for managing the protection of the ozone layer, and will also be made up of the Secretary of State for Industry and Commerce, the National Office of Meteorology, the National Institute of Environmental Protection and the General Directorate of Customs.', 'Dominican Republic', 'climate', 'in_force', '2000-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_14', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'mandatory', 'dominican republic', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca3efe33-ac1e-53ab-8a84-b7b1cf2bd51e', 'Dominican Republic Forest Technical Standards', 'Forest Technical Standards', 'The objectives of this Regulation are the following: 1. Contribute to the sustainable development of natural and planted forests and the promotion of commercial reforestation and for of protection in the Dominican Republic. 2. Regulate the development of the sawmill industry that processes wood from natural forests and plantations in the Dominican Republic. 3. Promote greater efficiency and control in the use of forest resources at the natural and planted forest level. 4. Promote the improvement of the living conditions of rural inhabitants, by generating jobs and improving environmental quality.', 'The objectives of this Regulation are the following: 1. Contribute to the sustainable development of natural and planted forests and the promotion of commercial reforestation and for of protection in the Dominican Republic. 2. Regulate the development of the sawmill industry that processes wood from natural forests and plantations in the Dominican Republic. 3. Promote greater efficiency and control in the use of forest resources at the natural and planted forest level. 4. Promote the improvement of the living conditions of rural inhabitants, by generating jobs and improving environmental quality.', 'The objectives of this Regulation are the following: 1. Contribute to the sustainable development of natural and planted forests and the promotion of commercial reforestation and for of protection in the Dominican Republic. 2. Regulate the development of the sawmill industry that processes wood from natural forests and plantations in the Dominican Republic. 3. Promote greater efficiency and control in the use of forest resources at the natural and planted forest level. 4. Promote the improvement of the living conditions of rural inhabitants, by generating jobs and improving environmental quality.', 'Dominican Republic', 'nature', 'in_force', '2000-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_17', ARRAY['sdg4', 'other sustainability policy', 'sdg9', 'sdg11', 'voluntary', 'dominican republic', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f7b17e7b-1a99-5ab7-b501-73ff5b24d53c', 'Dominican Republic General Application of Basic Rules of Good', 'Regulation for the General Application of Basic Rules of Good Agricultural Practices and Good Practices Livestock', 'The purpose of this Regulation is to establish the guidelines for the application of Good Agricultural Practices (BPA) and Good Livestock Practices (BPG) in agricultural production processes, as well as to establish the basic requirements that will apply in the production, packaging and transportation of agricultural products.', 'The purpose of this Regulation is to establish the guidelines for the application of Good Agricultural Practices (BPA) and Good Livestock Practices (BPG) in agricultural production processes, as well as to establish the basic requirements that will apply in the production, packaging and transportation of agricultural products.', 'The purpose of this Regulation is to establish the guidelines for the application of Good Agricultural Practices (BPA) and Good Livestock Practices (BPG) in agricultural production processes, as well as to establish the basic requirements that will apply in the production, packaging and transportation of agricultural products.', 'Dominican Republic', 'climate', 'in_force', '2000-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_2', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'dominican republic', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('999c97f2-1af1-5c13-852d-97cce1067015', 'Dominican Republic Environmental Standards for Operations of the Non-Metallic', 'Environmental Standards for Operations of the Non-Metallic Mining', 'The objective of these Standards is to establish the environmental requirements for non-metallic mining operations that are regulated by Law Nos. 123-71, 146-71 and 64-00, in accordance with the principles of environmental protection and sustainable use of natural resources, and protection of the health and life of people.', 'The objective of these Standards is to establish the environmental requirements for non-metallic mining operations that are regulated by Law Nos. 123-71, 146-71 and 64-00, in accordance with the principles of environmental protection and sustainable use of natural resources, and protection of the health and life of people.', 'The objective of these Standards is to establish the environmental requirements for non-metallic mining operations that are regulated by Law Nos. 123-71, 146-71 and 64-00, in accordance with the principles of environmental protection and sustainable use of natural resources, and protection of the health and life of people.', 'Dominican Republic', 'climate', 'in_force', '2000-01-01'::date, 'Dominican Republic', 'https://www.carrotsandsticks.org/policies/46_8', ARRAY['sdg3', 'other sustainability policy', 'voluntary', 'dominican republic', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d94baac-08dc-5cff-9182-6d2fd9b489f0', 'Ecuador''s Nationally Determined Contributions (NDC) - Paris Agreement', 'Ecuador''s Nationally Determined Contributions (NDC) - Paris Agreement', 'Ecuador''s Intended Nationally Determined Contribution (INDC) outlines the country''s commitment to addressing climate change through both mitigation and adaptation efforts. Ecuador acknowledges the global importance of climate action and expresses its intent to contribute towards the stabilization of greenhouse gas concentrations, focusing on sustainable development through its national policies. The INDC highlights Ecuador''s goal to decarbonize its energy matrix by increasing renewable energy, especially through hydroelectric power, and reducing emissions in the energy sector by 20-25% below the Business-as-Usual (BAU) scenario. Additionally, the country commits to sustainable forestry practices, including large-scale reforestation and forest restoration. The adaptation strategies focus on water resource management, agriculture, ecosystems, and enhancing the resilience of vulnerable regions. Ecuador plans to integrate climate change considerations into national planning and development processes. However, the success of these measures depends on international financial support.', 'Ecuador''s Intended Nationally Determined Contribution (INDC) outlines the country''s commitment to addressing climate change through both mitigation and adaptation efforts. Ecuador acknowledges the global importance of climate action and expresses its intent to contribute towards the stabilization of greenhouse gas concentrations, focusing on sustainable development through its national policies. The INDC highlights Ecuador''s goal to decarbonize its energy matrix by increasing renewable energy, especially through hydroelectric power, and reducing emissions in the energy sector by 20-25% below the Business-as-Usual (BAU) scenario. Additionally, the country commits to sustainable forestry practices, including large-scale reforestation and forest restoration. The adaptation strategies focus on water resource management, agriculture, ecosystems, and enhancing the resilience of vulnerable regions. Ecuador plans to integrate climate change considerations into national planning and development processes. However, the success of these measures depends on international financial support.', 'Ecuador''s Intended Nationally Determined Contribution (INDC) outlines the country''s commitment to addressing climate change through both mitigation and adaptation efforts. Ecuador acknowledges the global importance of climate action and expresses its intent to contribute towards the stabilization of greenhouse gas concentrations, focusing on sustainable development through its national policies. The INDC highlights Ecuador''s goal to decarbonize its energy matrix by increasing renewable energy, especially through hydroelectric power, and reducing emissions in the energy sector by 20-25% below the Business-as-Usual (BAU) scenario. Additionally, the country commits to sustainable forestry practices, including large-scale reforestation and forest restoration. The adaptation strategies focus on water resource management, agriculture, ecosystems, and enhancing the resilience of vulnerable regions. Ecuador plans to integrate climate change considerations into national planning and development processes. However, the success of these measures depends on international financial support.', 'Ecuador', 'climate', 'in_force', '2020-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_2', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg10', 'regulations', 'sdg7', 'mandatory', 'ecuador', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
